// generated by gen_matrix (full carrier composition matrix).
use vehje_bench_carrier as c;
use mockspace_bench_core::{timed, FfiBenchCall};
use mockspace_bench_macro::bench_variant;
#[allow(unused_imports)]
use std::sync::OnceLock;

#[bench_variant("carrier_disp_scatter_fntable", sizes = [64, 256, 1024, 4096, 16384])]
fn run<const N: usize>(input: &[u8; N], output: &mut [u8; 8]) -> FfiBenchCall {
    static PREP: OnceLock<Vec<u8>> = OnceLock::new(); let bytes = PREP.get_or_init(|| { let mut gp = c::GenParams::profile("scatter").unwrap(); gp.node_count = N; c::ir::encode(&c::generate(&gp), &c::ir::REC24) }); let d = c::ir::Decoded::parse(bytes, c::ir::REC24).unwrap(); let mut r = vec![0u64; d.node_count];
    const ITERS: usize = 16;
    timed! { run {
        let mut acc: u64 = 0;
        let mut k = 0usize;
        while k < ITERS {
            let seed = input[k % N] as u64 ^ (k as u64);
            c::interpret_fntable(&d, seed, &mut r); acc ^= c::checksum(&r);
            k += 1;
        }
        output.copy_from_slice(&acc.to_le_bytes());
    } }
}
